mapper.select:
select c.*, e.name as master_name, case when current_date > c.end_date then '已结课' when current_date < c.begin_date then '未开班' else '在读中' end as status
from clazz c left join emp e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.end_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc
